## 四、MCP Server开发
### 4.1 Python MCP Server
```python
from mcp.server import Server
from mcp.types import Tool, TextContent, Resource
import asyncio
# 创建Server
server = Server("enterprise-knowledge-server")
# 注册工具
@server.tool()
async def search_knowledge(query: str, max_results: int = 5) -> list[TextContent]:
    """在企业知识库中搜索相关文档。
    Args:
        query: 搜索关键词
        max_results: 最大返回数量，默认5
        Returns:
            相关文档片段列表
            """
            # 检索知识库
            docs = await vectorstore.similarity_search(query, k=max_results)
            return [
                TextContent(
                type="text",
                text=f"来源: {doc.metadata['source']}\n内容: {doc.page_content}"
                )
                for doc in docs
            ]
            @server.tool()
            async def get_document(doc_id: str) -> list[TextContent]:
                """根据文档ID获取完整文档内容。
                Args:
                    doc_id: 文档唯一标识
                    Returns:
                        完整文档内容
                        """
                        doc = await db.get_document(doc_id)
                        if not doc:
                            return [TextContent(type="text", text=f"文档{doc_id}不存在")]
                            return [TextContent(type="text", text=doc.content)]
                            # 注册资源
                            @server.resource()
                            async def get_config(uri: str) -> str:
                                """获取系统配置"""
                                if uri == "config://database":
                                    return await db.get_config("database")
                                    raise ValueError(f"Unknown resource: {uri}")
                                    # 启动
                                    async def main():
                                        from mcp.server.stdio import stdio_server
                                        async with stdio_server() as (read_stream, write_stream):
                                            await server.run(read_stream, write_stream,
                                            server.create_initialization_options())
                                            if __name__ == "__main__":
                                                asyncio.run(main())
```
### 4.2 TypeScript MCP Server
```typescript
// TypeScript MCP Server 官方 SDK 示例
import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
import {
  CallToolRequestSchema,
  ListToolsRequestSchema,
} from "@modelcontextprotocol/sdk/types.js";

const server = new Server(
  { name: "knowledge-server", version: "1.0.0" },
  { capabilities: { tools: {} } }
);

// 列出可用工具
server.setRequestHandler(ListToolsRequestSchema, async () => ({
  tools: [
    {
      name: "search_knowledge",
      description: "在企业知识库中搜索相关文档",
      inputSchema: {
        type: "object",
        properties: {
          query: { type: "string", description: "搜索关键词" },
          maxResults: { type: "number", description: "最大返回数量", default: 5 }
        },
        required: ["query"]
      }
    }
  ]
}));

// 处理工具调用
server.setRequestHandler(CallToolRequestSchema, async (request) => {
  const { name, arguments: args } = request.params;
  if (name === "search_knowledge") {
    const results = await searchKnowledge(args.query, args.maxResults);
    return { content: [{ type: "text", text: JSON.stringify(results) }] };
  }
  throw new Error(`Unknown tool: ${name}`);
});

// 启动服务器
async function main() {
  const transport = new StdioServerTransport();
  await server.connect(transport);
}
main();
```
